// Generates supabase/migrations/pk_0002_seed_catalog.sql from
// data/services.json + data/packages.json, so the database's price
// table (used to price orders server-side) can never drift from what
// the site displays. Re-run after any price change, then apply the
// regenerated file:  node scripts/gen-seed-sql.mjs
// Catalogue V2: lines and packages that are no longer in the JSON are
// switched off (active = false), never deleted, so past orders keep their
// references and audit trail.
import { readFileSync, writeFileSync } from 'node:fs';

const services = JSON.parse(readFileSync(new URL('../data/services.json', import.meta.url))).services;
const packages = JSON.parse(readFileSync(new URL('../data/packages.json', import.meta.url))).packages;

const q = (v) => (v === null || v === undefined ? 'null' : typeof v === 'number' || typeof v === 'boolean' ? String(v) : "'" + String(v).replace(/'/g, "''") + "'");

const lineRows = [];
const lineIds = [];
for (const s of services) {
  for (const l of s.lines) {
    lineIds.push(l.id);
    lineRows.push(`  (${q(l.id)}, ${s.no}, ${q(s.name)}, ${q(l.model)}, ${l.price}, ${q(l.unit)}, ${q(l.days ?? null)}, ${q(!!l.from)})`);
  }
}

const pkgRows = packages.map((p) => {
  const setupItems = (p.setup_items || []).map((it) => {
    const o = { label: it.label };
    if (it.line) o.line = it.line;
    if (it.qty) o.qty = it.qty;
    return o;
  });
  const isFrom = !!(p.monthly_from || p.one_off_from);
  return `  (${q(p.id)}, ${q(p.name)}, ${q(p.monthly ?? null)}, ${q(p.setup ?? null)}, ${q(p.one_off ?? null)}, ${p.min_months || 0}, ${p.due_days || 0}, ${q(JSON.stringify(setupItems))}::jsonb, ${q(!!p.quote_only)}, ${q(isFrom)}, ${q(p.section ?? null)})`;
});

const allowRows = [];
for (const p of packages) {
  for (const a of p.allowances || []) {
    allowRows.push(`  (${q(p.id)}, ${q(a.key)}, ${q(a.label)}, ${a.qty}, null, ${q(a.extra_line ?? null)})`);
  }
}
const pkgIds = packages.map((p) => q(p.id)).join(', ');

const sql = `-- GENERATED by scripts/gen-seed-sql.mjs from data/services.json and
-- data/packages.json. Do not edit by hand; edit the JSON and re-run.
-- Upserts, so it is safe to re-apply after a price change. Requires
-- pk_0004_catalogue_v2.sql (service numbers above 56, package flags).

insert into public.pk_catalog_lines (line_id, service_no, service_name, model, price, unit, days, is_from) values
${lineRows.join(',\n')}
on conflict (line_id) do update set service_no = excluded.service_no, service_name = excluded.service_name, model = excluded.model,
  price = excluded.price, unit = excluded.unit, days = excluded.days, is_from = excluded.is_from, active = true;

-- Retired lines stay in the table (orders may reference them) but can no longer be ordered.
update public.pk_catalog_lines set active = false
where line_id not in (${lineIds.map(q).join(', ')});

insert into public.pk_packages (id, name, monthly, setup, one_off, min_months, due_days, setup_items, quote_only, is_from, section) values
${pkgRows.join(',\n')}
on conflict (id) do update set name = excluded.name, monthly = excluded.monthly, setup = excluded.setup, one_off = excluded.one_off,
  min_months = excluded.min_months, due_days = excluded.due_days, setup_items = excluded.setup_items,
  quote_only = excluded.quote_only, is_from = excluded.is_from, section = excluded.section, active = true;

-- Retired packages stay for existing subscriptions but can no longer be bought.
update public.pk_packages set active = false where id not in (${pkgIds});

delete from public.pk_package_allowances where package_id in (${pkgIds});
insert into public.pk_package_allowances (package_id, item_key, label, qty, service_no, extra_line_id) values
${allowRows.join(',\n')};
`;

writeFileSync(new URL('../supabase/migrations/pk_0002_seed_catalog.sql', import.meta.url), sql);
console.log(`Wrote pk_0002_seed_catalog.sql: ${lineRows.length} price lines, ${pkgRows.length} packages, ${allowRows.length} allowances.`);
